/**
 * SPA HTML HANDLER
 *
 * Serves index.html for browser navigation requests with:
 *   - CSP nonce injection (from shield middleware)
 *   - Public env vars injection (globalThis.__ENV__)
 *   - Build ID injection for cache-busting
 *   - Course count injection for JSON-LD structured data
 *   - Per-route SEO rewriting (title/description/canonical/OG/JSON-LD)
 *     generated by api/lib/seo-meta.ts — critical because the raw HTML of a
 *     SPA is identical for every route and Google indexes the raw HTML.
 *   - Canonical `Link` HTTP header override (HuggingFace Spaces injects a
 *     `rel=canonical` header pointing at huggingface.co which actively harms
 *     indexing of the custom domain).
 *   - HTTP 404 for unknown paths (soft-404 prevention) while still serving
 *     the SPA HTML so React renders the NotFound page for humans.
 *
 * Registered BEFORE serveStatic so browser navigations (Accept: text/html)
 * get the nonce-injected HTML instead of the raw file. Non-HTML requests
 * (assets, API) fall through to serveStatic / API routes.
 */

import { createMiddleware } from "hono/factory";
import {
  applySeoToHtml,
  isKnownSpaRoute,
  isNoindexPath,
  resolveRouteSeo,
  robotsDirectiveFor,
} from "./seo-meta.js";

// ── HTML template cache ──
let cachedHtmlTemplate: string | null = null;
let cachedHtmlTemplateMtime = 0;

async function getHtmlTemplate(): Promise<string> {
  try {
    const { stat, readFile } = await import("node:fs/promises");
    const filePath = "./dist/public/index.html";
    const fileStat = await stat(filePath);
    if (fileStat.mtimeMs !== cachedHtmlTemplateMtime) {
      cachedHtmlTemplate = await readFile(filePath, "utf-8");
      cachedHtmlTemplateMtime = fileStat.mtimeMs;
    }
  } catch {
    if (!cachedHtmlTemplate) {
      throw new Error("index.html not found");
    }
  }
  return cachedHtmlTemplate!;
}

// ── Course count cache ──
let cachedCourseCount = 0;
let courseCountExpiry = 0;

async function getCourseCount(): Promise<number> {
  if (Date.now() > courseCountExpiry) {
    try {
      const { db } = await import("../queries/connection.js");
      const { courses } = await import("@db/schema");
      const { count, eq } = await import("drizzle-orm");
      const result = await db
        .select({ count: count() })
        .from(courses)
        .where(eq(courses.isPublished, true));
      cachedCourseCount = Number(result[0]?.count ?? 0);
    } catch {
      // Keep previous value on error
    }
    courseCountExpiry = Date.now() + 5 * 60 * 1000; // Refresh every 5 minutes
  }
  return cachedCourseCount;
}

/** Strip query string and trailing slash (except root) for route matching. */
function normalizePath(rawPath: string): string {
  const noQuery = rawPath.split("?")[0].split("#")[0];
  if (noQuery.length > 1) {
    return noQuery.replace(/\/+$/, "") || "/";
  }
  return noQuery;
}

/**
 * Inject CSP nonce + public env vars into the HTML.
 * Nonce attributes are required on every inline <script> for CSP compliance.
 */
async function applyNonce(
  html: string,
  nonce: string,
  getBuildId: () => string | null
): Promise<string> {
  let out = html.replace(
    /<head([^>]*)>/,
    `<head$1><meta name="csp-nonce" content="${nonce}">`
  );
  // Add nonce attribute to ALL inline <script> tags (those without src).
  out = out.replaceAll(/<script(?![^>]*\ssrc=)([^>]*)>/g, `<script nonce="${nonce}"$1>`);

  try {
    // Inject public env vars directly into HTML
    const { getPublicEnvKeys } = await import("./env.js");
    const publicEnv = getPublicEnvKeys();
    const currentBuildId = getBuildId();
    const envWithBuild = {
      ...publicEnv,
      buildId: currentBuildId || process.env.BUILD_ID || "dev",
    };
    const envScript = `<script nonce="${nonce}">globalThis.__ENV__=${JSON.stringify(envWithBuild)};</script>`;
    out = out.replace(/<meta name="csp-nonce"[^>]*>/, `$&${envScript}`);
  } catch {
    // env injection is best-effort — page still renders without it
  }
  return out;
}

/**
 * SPA HTML handler middleware.
 *
 * For browser navigation requests, serves index.html with:
 *   - CSP nonce injected into <head> and inline <script> tags
 *   - globalThis.__ENV__ injected with public env vars + buildId
 *   - Course count injected for JSON-LD structured data
 *   - Cache-busting via %%CACHE_BUST%% placeholder replacement
 *   - Per-route SEO meta rewriting + canonical Link header
 *   - 404 status for unknown routes (SPA still renders NotFound UI)
 *
 * Non-HTML and API requests fall through to next().
 *
 * @param getBuildId - Getter function that returns the current buildId (captured by closure at request time)
 */
export function createSpaHandler(getBuildId: () => string | null) {
  return createMiddleware(async (c, next) => {
    const accept = c.req.header("accept") ?? "";
    const wantsHtml = accept.includes("text/html");
    const path = c.req.path;

    // Skip if this isn't a browser navigation request
    if (!wantsHtml) {
      return next(); // → serveStatic handles static assets
    }

    // Skip API routes
    if (path.startsWith("/api/")) {
      return next();
    }

    // Skip requests that look like static assets (even if Accept: text/html
    // is present, which can happen with some browsers/prefetchers).
    // `.html` MUST be in this list: raw .html files in dist/public (e.g.
    // `google<token>.html` for Google Search Console verification) have to be
    // served byte-for-byte by serveStatic. The Google verifier sends an
    // `Accept: text/html` header, so without this entry the request would be
    // captured below, rewritten to index.html (404) and verification would fail.
    if (path.match(/\.(js|css|html?|png|jpg|jpeg|svg|ico|woff2?|ttf|eot|webmanifest|webp|avif|gif|map|txt|xml|json)$/)) {
      return next(); // → serveStatic serves the raw file (or 404 if missing)
    }

    const routePath = normalizePath(path);
    const knownRoute = isKnownSpaRoute(routePath);

    try {
      let html = await getHtmlTemplate();
      const nonce = c.get("cspNonce") as string | undefined;

      const courseCount = await getCourseCount();
      html = html.replaceAll('"%%OFFER_COUNT%%"', `"${courseCount}"`);
      html = html.replaceAll("%%CACHE_BUST%%", process.env.BUILD_ID || "dev");

      // ── Unknown SPA paths → real HTTP 404 (soft-404 prevention) ─────────
      // React still renders the NotFound page for humans; Google correctly
      // sees 404 instead of an infinite space of duplicate home pages.
      if (!knownRoute) {
        c.header("X-Robots-Tag", "noindex, nofollow");
        if (nonce) {
          const withNonce = await applyNonce(html, nonce, getBuildId);
          return c.html(withNonce, 404);
        }
        return c.html(html, 404);
      }

      // ── Known route: per-route SEO rewriting ────────────────────────────
      const noindex = isNoindexPath(routePath);
      try {
        const seo = await resolveRouteSeo(routePath);
        const verifications = {
          google: process.env.GOOGLE_SITE_VERIFICATION || undefined,
          bing: process.env.BING_SITE_VERIFICATION || undefined,
        };
        html = applySeoToHtml(html, seo, { noindex, verifications });

        // Canonical Link header — fights the HF Spaces injected canonical
        // (huggingface.co) that tells Google not to index the custom domain.
        c.header("Link", `<${seo.canonical}>; rel="canonical"`);
      } catch (seoErr) {
        // SEO rewriting must never break page delivery.
        console.error(
          "[SPA] SEO rewrite failed",
          seoErr instanceof Error ? seoErr.message : seoErr
        );
      }

      if (noindex) {
        c.header("X-Robots-Tag", robotsDirectiveFor(routePath));
      }

      if (nonce) {
        const withNonce = await applyNonce(html, nonce, getBuildId);
        return c.html(withNonce);
      }
      return c.html(html);
    } catch {
      // Aggressive cache-busting on this 404 — prevents CDN from caching it
      c.header("Cache-Control", "no-store, no-cache, must-revalidate, proxy-revalidate");
      c.header("Surrogate-Control", "no-store");
      c.header("Pragma", "no-cache");
      c.header("Expires", "0");
      return c.json({ error: "Not Found" }, 404);
    }
  });
}
